import math
from fractions import Fraction
from itertools import permutations

EPS = 1e-12
TOL = 1e-9
failures = []


def report(ok, name, detail=''):
    if ok:
        print('OK', name, detail)
    else:
        failures.append((name, detail))
        print('FAIL', name, detail)


def close(a, b, tol=TOL):
    return abs(a - b) <= tol * max(1.0, abs(a), abs(b))


def vec_close(a, b, tol=TOL):
    if len(a) != len(b):
        return False
    return all(close(x, y, tol) for x, y in zip(a, b))


def mean_masked(rows, valid):
    if not rows:
        raise ValueError('empty rows')
    d = len(rows[0])
    acc = [Fraction(0) for _ in range(d)]
    count = 0
    for row, ok in zip(rows, valid):
        if ok:
            count += 1
            if len(row) != d:
                raise ValueError('ragged rows')
            for j in range(d):
                acc[j] += Fraction(row[j])
    if count == 0:
        raise ValueError('empty valid set')
    return tuple(x / count for x in acc)


def mean_ref(valid_rows):
    if not valid_rows:
        raise ValueError('empty valid set')
    d = len(valid_rows[0])
    out = []
    for j in range(d):
        out.append(sum(Fraction(row[j]) for row in valid_rows) / len(valid_rows))
    return tuple(out)


def normalize(vec, eps=EPS):
    n2 = 0.0
    for x in vec:
        xf = float(x)
        n2 += xf * xf
    if n2 <= eps * eps:
        return tuple(0.0 for _ in vec), True
    inv = 1.0 / math.sqrt(n2)
    return tuple(float(x) * inv for x in vec), False


def encode_masked(rows, valid):
    p = mean_masked(rows, valid)
    e, z = normalize(p)
    return e, z, p


def pad_rows(seq, width, side, fill):
    if len(seq) > width:
        raise ValueError('too long')
    rows = []
    valid = []
    if side == 'right':
        rows.extend(seq)
        valid.extend([True] * len(seq))
        for _ in range(width - len(seq)):
            rows.append(fill)
            valid.append(False)
    else:
        for _ in range(width - len(seq)):
            rows.append(fill)
            valid.append(False)
        rows.extend(seq)
        valid.extend([True] * len(seq))
    return rows, valid


def block_mask(lengths):
    total = sum(lengths)
    m = [[False for _ in range(total)] for _ in range(total)]
    off = 0
    for n in lengths:
        for i in range(n):
            for j in range(n):
                m[off + i][off + j] = True
        off += n
    return m


def global_mask(lengths):
    total = sum(lengths)
    return [[True for _ in range(total)] for _ in range(total)]


def mask_problems(lengths, m):
    total = sum(lengths)
    bounds = []
    off = 0
    for n in lengths:
        bounds.append((off, off + n))
        off += n
    problems = []
    for si, (a, b) in enumerate(bounds):
        for i in range(a, b):
            for j in range(total):
                expected = a <= j < b
                if m[i][j] != expected:
                    problems.append((si, i, j, m[i][j], expected))
    return problems


def rerank(ids, scores):
    if len(ids) != len(scores):
        raise ValueError('length mismatch')
    src = {}
    for i, s in zip(ids, scores):
        if i in src:
            raise ValueError('duplicate id')
        src[i] = float(s)
    order = sorted(src, key=lambda x: (-src[x], x))
    return [(x, src[x]) for x in order], src


def bad_stable(ids, scores):
    src = {i: float(s) for i, s in zip(ids, scores)}
    order = sorted(ids, key=lambda x: -src[x])
    return [(x, src[x]) for x in order], src


def bad_aligned(ids, scores):
    order, src = rerank(ids, scores)
    return [(order[i], float(scores[i])) for i in range(len(order))]


def dot(u, v):
    return sum(float(x) * float(y) for x, y in zip(u, v))


def cosine(u, v):
    nu = math.sqrt(sum(float(x) * float(x) for x in u))
    nv = math.sqrt(sum(float(x) * float(x) for x in v))
    if nu <= EPS or nv <= EPS:
        raise ValueError('zero norm')
    return dot(u, v) / (nu * nv)


def rank_by(ids, vectors, q, metric):
    if metric == 'cosine':
        scores = [cosine(q, vectors[i]) for i in ids]
    else:
        scores = [dot(q, vectors[i]) for i in ids]
    order, src = rerank(ids, scores)
    return order


def cache_key(artifact, text, trunc, pooling, normalize_name, dtype):
    return (artifact, text, trunc, pooling, normalize_name, dtype)


def bad_cache_key(artifact, text, trunc, pooling, normalize_name, dtype):
    return (artifact, text, pooling, normalize_name, dtype)


fill = (100, 100)
ref_valid = [(1, 0), (0, 1)]
ref_p = mean_ref(ref_valid)
e_good, z_good, p_good = encode_masked([(1, 0), (0, 1), fill], [True, True, False])
report(p_good == ref_p, 'mean pooling excludes padding', str(p_good))
s = 1.0 / math.sqrt(2.0)
report(vec_close(e_good, (s, s)), 'normalized mean example', str(e_good))

bad_p = mean_masked([(1, 0), (0, 1), fill], [True, True, True])
report(p_good == ref_p, 'positive control pooling reference', str(ref_p))
report(bad_p != ref_p, 'negative control padding inclusion detected', str(bad_p))
last_vec, _ = normalize(fill)
report(not vec_close(last_vec, e_good), 'negative control fixed last row detected', str(last_vec))

seq = [(3, 0), (0, 4), (5, 5)]
ref_seq = mean_ref(seq)
for side in ('right', 'left'):
    rows, valid = pad_rows(seq, 5, side, fill)
    e, z, p = encode_masked(rows, valid)
    report(p == ref_seq, 'padding layout preserves pooled value ' + side, str(p))
    expected, _ = normalize(ref_seq)
    report(vec_close(e, expected), 'padding layout preserves normalized vector ' + side, str(e))

rows_bad, valid_bad = pad_rows(seq, 5, 'right', fill)
valid_bad = [True] * 5
bad_layout = mean_masked(rows_bad, valid_bad)
report(bad_layout != ref_seq, 'negative control right padding counted detected', str(bad_layout))

try:
    mean_masked([(1, 0)], [False])
    empty_ok = False
except ValueError:
    empty_ok = True
report(empty_ok, 'empty valid pooling set rejected')

z_vec, z_flag = normalize((0, 0))
report(z_flag and z_vec == (0.0, 0.0), 'declared zero norm branch returns zero vector', str(z_vec))

lengths = [2, 3, 4]
bm = block_mask(lengths)
gm = global_mask(lengths)
report(mask_problems(lengths, bm) == [], 'block diagonal mask has only same-request visibility')
gprob = mask_problems(lengths, gm)
report(len(gprob) > 0, 'negative control global mask cross-request visibility detected', str(len(gprob)))

score_map = {'a': 0.5, 'b': 0.9, 'c': 0.5, 'd': 0.1}
expected_order = [('b', 0.9), ('a', 0.5), ('c', 0.5), ('d', 0.1)]
ids0 = ['d', 'c', 'b', 'a']
scores0 = [score_map[i] for i in ids0]
order0, src0 = rerank(ids0, scores0)
report(order0 == expected_order, 'stable tie order by candidate id', str(order0))

all_perm_ok = True
for perm in permutations(['a', 'b', 'c', 'd']):
    scores = [score_map[i] for i in perm]
    order, _ = rerank(list(perm), scores)
    if order != expected_order:
        all_perm_ok = False
        break
report(all_perm_ok, 'rerank order invariant under candidate permutation')

bad_order, _ = bad_stable(ids0, scores0)
report(bad_order != expected_order, 'negative control input-order tie detected', str(bad_order))

misaligned = bad_aligned(ids0, scores0)
misaligned_ok = all(abs(sc - score_map[i]) <= TOL for i, sc in misaligned)
report(not misaligned_ok, 'negative control score-id misalignment detected', str(misaligned))

q = (1, 1)
vecs = {'a': (10, 0), 'b': (1, 1)}
cos_order = rank_by(['a', 'b'], vecs, q, 'cosine')
dot_order = rank_by(['a', 'b'], vecs, q, 'dot')
report([x for x, _ in cos_order] == ['b', 'a'], 'cosine ranking uses normalized direction', str(cos_order))
report([x for x, _ in dot_order] == ['a', 'b'], 'unnormalized dot ranking differs', str(dot_order))
report([x for x, _ in dot_order] != [x for x, _ in cos_order], 'negative control dot-as-cosine detected')

k64 = cache_key('A1', 'doc text', 64, 'mean', 'l2', 'fp32')
k128 = cache_key('A1', 'doc text', 128, 'mean', 'l2', 'fp32')
report(k64 != k128, 'cache key distinguishes truncation')
b64 = bad_cache_key('A1', 'doc text', 64, 'mean', 'l2', 'fp32')
b128 = bad_cache_key('A1', 'doc text', 128, 'mean', 'l2', 'fp32')
report(b64 == b128, 'negative control missing truncation key collides')

if failures:
    print('SUMMARY failures=' + str(len(failures)) + '; scope=CPU logical model only')
    raise SystemExit(1)
print('SUMMARY failures=0; scope=CPU logical model only; no model forward, GPU measurement, or quality experiment')
